// FILE: frontend/src/App.js
//
// --- VERSION 1.0.0 CHANGE ---
// - This file now acts as the main router for the application.
// - It uses `react-router-dom` to render either the `LogList` component
//   for the main page or the `LogDetail` component for the detail view.
// -----------------------------

import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import LogList from './LogList';
import LogDetail from './LogDetail';

function App() {
  return (
    <Router>
      <div className="bg-gray-900 text-white min-h-screen font-sans">
        <div className="container mx-auto p-4 md:p-8">
          <header className="mb-8">
            <a href="/" className="text-4xl font-bold text-cyan-400 hover:text-cyan-300 no-underline">
              Jeep Diagnostics Dashboard
            </a>
          </header>
          <main>
            <Routes>
              <Route path="/" element={<LogList />} />
              <Route path="/logs/:logId" element={<LogDetail />} />
            </Routes>
          </main>
          <footer className="text-center mt-8 text-gray-500 text-sm">
            <p>Jeep Log Processor v1.0.0</p>
          </footer>
        </div>
      </div>
    </Router>
  );
}

export default App;
